    // Add 5 creatures: should cost {3}{R} = 4 mana.
    for _ in 0..5 {
        ready_creature(&mut state, P0, 1, 1);
    }
    let modified = ba.modified_cost(&state, &reg).unwrap();
    assert_eq!(modified.mana_value(), 4, "With 5 creatures, Blasphemous Act should cost {{3}}{{R}}");

